"use client"

import { useEffect, useRef, useState } from "react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/cn"

import { mountGlLoop, type GlContext, type GlFrame, type GlLoopHandle, type GlPair, type GlTarget } from "./gl/gl-loop"
import { compileField, type FieldProgram } from "./reaction-diffusion-shaders"

/** original implementation. Gray-Scott field grown from a built-in pattern. */

export type ReactionPattern = "spots" | "print" | "coral"

export interface ReactionDiffusionFieldProps {
  pattern?: ReactionPattern
  speed?: number
  intensity?: number
  colors?: readonly string[]
  className?: string
}

export interface GrayScottRates {
  feed: number
  kill: number
}

type Rgb = [number, number, number]

interface Tuning {
  pattern: ReactionPattern
  speed: number
  intensity: number
  colors: readonly string[] | undefined
}
interface FieldSession {
  draw: (frame: GlFrame) => void
  dispose: () => void
}

const RATES: Record<ReactionPattern, GrayScottRates> = {
  spots: { feed: 0.035, kill: 0.065 },
  print: { feed: 0.037, kill: 0.06 },
  coral: { feed: 0.0545, kill: 0.062 },
}

const SPOTS: readonly (readonly [number, number, number])[] = [
  [0.375, 0.375, 0.0625],
  [0.625, 0.5, 0.046875],
  [0.5, 0.6875, 0.0625],
]

const BRANCHES: readonly (readonly [number, number, number, number, number])[] = [
  [0.5, 0.8125, 0.5, 0.1875, 0.03125],
  [0.5, 0.5, 0.25, 0.25, 0.0234375],
  [0.5, 0.375, 0.75, 0.1875, 0.0234375],
  [0.5, 0.625, 0.6875, 0.5, 0.0234375],
]

const TOKENS = ["--primary", "--chart-2", "--chart-4"] as const
const FALLBACK: readonly Rgb[] = [
  [0.2, 0.28, 0.45],
  [0.12, 0.4, 0.38],
  [0.55, 0.32, 0.16],
]

const GRID = 128

export function patternRates(pattern: ReactionPattern): GrayScottRates {
  const rates = RATES[pattern]
  return { feed: rates.feed, kill: rates.kill }
}

export function fieldPattern(value: string | undefined): ReactionPattern {
  if (value === "print" || value === "coral") return value
  return "spots"
}

function unit(value: number, fallback: number): number {
  if (!Number.isFinite(value)) return fallback
  if (value < 0) return 0
  if (value > 1) return 1
  return value
}

function clamp01(value: number): number {
  if (value < 0) return 0
  if (value > 1) return 1
  return value
}

/** 五点和的拉普拉斯由调用方算好。扩散 0.16 / 0.08。强度只乘反应项。 */
export function grayScottStep(
  u: number,
  v: number,
  lapU: number,
  lapV: number,
  rates: GrayScottRates,
  dt: number,
  intensity: number,
): { u: number; v: number } {
  const step = dt > 0 ? dt : 0
  const react = unit(intensity, 0)
  const uvv = u * v * v * react
  const nextU = u + step * (0.16 * lapU - uvv + rates.feed * react * (1 - u))
  const nextV = v + step * (0.08 * lapV + uvv - (rates.feed + rates.kill) * react * v)
  return { u: clamp01(nextU), v: clamp01(nextV) }
}

/** 0 秒不走。否则大约每秒 240 步，封在 1 到 16。 */
export function stepsForFrame(speed: number, seconds: number): number {
  if (!(seconds > 0)) return 0
  const rate = !Number.isFinite(speed) ? 1 : Math.min(2.5, Math.max(0.25, speed))
  const raw = Math.round(seconds * rate * 240)
  if (raw < 1) return 1
  if (raw > 16) return 16
  return raw
}

/** 浓度乘上强度。强度 0 仍留 0.25，避免图案灭掉。 */
export function dyeWeight(concentration: number, intensity: number): number {
  const chem = concentration > 0 ? clamp01(concentration) : 0
  return chem * (0.25 + 0.75 * unit(intensity, 0.75))
}

function insideDisk(x: number, y: number, cx: number, cy: number, radius: number): boolean {
  const dx = x - cx
  const dy = y - cy
  return dx * dx + dy * dy <= radius * radius
}

function spotsAt(x: number, y: number): number {
  for (const [cx, cy, radius] of SPOTS) {
    if (insideDisk(x, y, cx, cy, radius)) return 1
  }
  return 0
}

function printAt(x: number, y: number): number {
  const dx = x - 0.5
  const dy = y - 0.5
  if (dx * dx + dy * dy > 0.140625) return 0
  const height = y - 0.25 - 2 * dx * dx
  const mod = height % 0.125
  const phase = mod < 0 ? mod + 0.125 : mod
  const dist = phase < 0.0625 ? phase : 0.125 - phase
  return dist <= 0.015625 ? 1 : 0
}

function nearSegment(px: number, py: number, ax: number, ay: number, bx: number, by: number, half: number): boolean {
  const abx = bx - ax
  const aby = by - ay
  const ab2 = abx * abx + aby * aby
  let t = ab2 === 0 ? 0 : ((px - ax) * abx + (py - ay) * aby) / ab2
  if (t < 0) t = 0
  else if (t > 1) t = 1
  const dx = px - (ax + abx * t)
  const dy = py - (ay + aby * t)
  return dx * dx + dy * dy <= half * half
}

function coralAt(x: number, y: number): number {
  for (const [ax, ay, bx, by, half] of BRANCHES) {
    if (nearSegment(x, y, ax, ay, bx, by, half)) return 1
  }
  return 0
}

/** 催化剂 v。斑点是圆盘，指纹是拱形脊，珊瑚是分叉线段。 */
export function seedChemicals(pattern: ReactionPattern, x: number, y: number): { u: number; v: number } {
  let v = spotsAt(x, y)
  if (pattern === "print") v = printAt(x, y)
  else if (pattern === "coral") v = coralAt(x, y)
  return { u: v > 0 ? 0.5 : 1, v }
}

function parseCssColor(input: string): Rgb | null {
  const text = input.trim()
  const hex = /^#([\da-f]{3}|[\da-f]{6})$/i.exec(text)
  const body = hex?.[1]
  if (body) {
    const full = body.length === 3 ? [...body].map((char) => char + char).join("") : body
    const value = Number.parseInt(full, 16)
    return [((value >> 16) & 255) / 255, ((value >> 8) & 255) / 255, (value & 255) / 255]
  }
  const rgb = /^rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)/i.exec(text)
  if (!rgb?.[1] || !rgb[2] || !rgb[3]) return null
  return [Number(rgb[1]) / 255, Number(rgb[2]) / 255, Number(rgb[3]) / 255]
}

function colorOn(host: HTMLElement, css: string): Rgb | null {
  const text = css.trim()
  if (!text) return null
  const direct = parseCssColor(text)
  if (direct) return direct
  const previous = host.style.color
  host.style.color = text
  const resolved = parseCssColor(getComputedStyle(host).color)
  host.style.color = previous
  return resolved
}

function fallbackAt(index: number): Rgb {
  return FALLBACK[index] ?? FALLBACK[0] ?? [0.2, 0.28, 0.45]
}

function tokenColor(host: HTMLElement, style: CSSStyleDeclaration, index: number): Rgb {
  const token = TOKENS[index] ?? "--primary"
  const raw = style.getPropertyValue(token).trim()
  if (!raw) return fallbackAt(index)
  return colorOn(host, raw) ?? fallbackAt(index)
}

function themeColors(host: HTMLElement): [Rgb, Rgb, Rgb] {
  const style = getComputedStyle(host)
  return [tokenColor(host, style, 0), tokenColor(host, style, 1), tokenColor(host, style, 2)]
}

function paletteOf(host: HTMLElement, colors: readonly string[] | undefined): [Rgb, Rgb, Rgb] {
  if (!colors || colors.length === 0) return themeColors(host)
  return [
    colorOn(host, colors[0] ?? "") ?? fallbackAt(0),
    colorOn(host, colors[1] ?? "") ?? fallbackAt(1),
    colorOn(host, colors[2] ?? "") ?? fallbackAt(2),
  ]
}

function backdropOf(host: HTMLElement): Rgb {
  const style = getComputedStyle(host)
  return parseCssColor(style.backgroundColor) ?? colorOn(host, "var(--background)") ?? [0.97, 0.96, 0.94]
}

function stillPaint(pattern: ReactionPattern, colors: readonly string[] | undefined) {
  const a = colors?.[0] || "var(--primary)"
  const b = colors?.[1] || "var(--chart-2)"
  const c = colors?.[2] || "var(--chart-4)"
  if (pattern === "print") {
    return `repeating-radial-gradient(circle at 50% 58%, color-mix(in oklab, ${a} 78%, transparent) 0 2px, transparent 2px 11px), radial-gradient(70% 76% at 50% 58%, transparent 42%, var(--background) 74%)`
  }
  if (pattern === "coral") {
    return [
      `linear-gradient(90deg, transparent 47%, color-mix(in oklab, ${a} 82%, transparent) 47% 53%, transparent 53%)`,
      `linear-gradient(38deg, transparent 42%, color-mix(in oklab, ${b} 74%, transparent) 42% 48%, transparent 48%)`,
      `linear-gradient(-32deg, transparent 44%, color-mix(in oklab, ${c} 74%, transparent) 44% 50%, transparent 50%)`,
    ].join(",")
  }
  return [
    `radial-gradient(14% 16% at 38% 38%, color-mix(in oklab, ${a} 82%, transparent), transparent 70%)`,
    `radial-gradient(11% 13% at 62% 50%, color-mix(in oklab, ${b} 76%, transparent), transparent 72%)`,
    `radial-gradient(13% 15% at 50% 69%, color-mix(in oklab, ${c} 74%, transparent), transparent 70%)`,
  ].join(",")
}

function paint(gl: GlContext, loop: GlLoopHandle, compiled: FieldProgram, target: GlTarget | null, width: number, height: number) {
  gl.bindFramebuffer(gl.FRAMEBUFFER, target?.framebuffer ?? null)
  gl.viewport(0, 0, width, height)
  gl.useProgram(compiled.program)
  loop.draw()
}

function createSeedTexture(gl: GlContext): WebGLTexture | null {
  const texture = gl.createTexture()
  if (!texture) return null
  gl.bindTexture(gl.TEXTURE_2D, texture)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE)
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, 1, 1, 0, gl.RGBA, gl.UNSIGNED_BYTE, new Uint8Array([255, 0, 0, 255]))
  gl.bindTexture(gl.TEXTURE_2D, null)
  return texture
}

function writeSeed(gl: GlContext, texture: WebGLTexture, pattern: ReactionPattern) {
  const data = new Uint8Array(GRID * GRID * 4)
  for (let y = 0; y < GRID; y += 1) {
    for (let x = 0; x < GRID; x += 1) {
      const chem = seedChemicals(pattern, (x + 0.5) / GRID, (y + 0.5) / GRID)
      const index = (y * GRID + x) * 4
      data[index] = Math.round(chem.u * 255)
      data[index + 1] = Math.round(chem.v * 255)
      data[index + 3] = 255
    }
  }
  gl.bindTexture(gl.TEXTURE_2D, texture)
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, GRID, GRID, 0, gl.RGBA, gl.UNSIGNED_BYTE, data)
  gl.bindTexture(gl.TEXTURE_2D, null)
}

function uniform3(gl: GlContext, loc: WebGLUniformLocation | null, color: Rgb) {
  gl.uniform3f(loc, color[0], color[1], color[2])
}

function startSession(loop: GlLoopHandle, host: HTMLElement, tuning: { readonly current: Tuning }): FieldSession | null {
  const gl = loop.gl
  const webgl2 = typeof (gl as WebGL2RenderingContext).drawBuffers === "function"
  const compiled = compileField(gl, webgl2)
  if (!compiled) return null
  const [seed, step, display] = compiled
  const pair = loop.createPair(GRID, GRID)
  const seedTex = createSeedTexture(gl)
  if (!pair || !seedTex) {
    pair?.dispose()
    if (seedTex) gl.deleteTexture(seedTex)
    gl.deleteProgram(seed.program)
    gl.deleteProgram(step.program)
    gl.deleteProgram(display.program)
    return null
  }
  gl.disable(gl.BLEND)
  gl.disable(gl.DEPTH_TEST)
  gl.useProgram(seed.program)
  gl.uniform1i(seed.loc("uSeed"), 0)
  gl.useProgram(step.program)
  gl.uniform1i(step.loc("uState"), 0)
  gl.uniform2f(step.loc("uTexel"), 1 / GRID, 1 / GRID)
  gl.useProgram(display.program)
  gl.uniform1i(display.loc("uState"), 0)
  let seeded: ReactionPattern | null = null

  function drop(target: GlPair) {
    target.dispose()
    gl.deleteTexture(seedTex)
    gl.deleteProgram(seed.program)
    gl.deleteProgram(step.program)
    gl.deleteProgram(display.program)
  }

  return {
    draw(frame) {
      const pattern = fieldPattern(tuning.current.pattern)
      const react = unit(tuning.current.intensity, 0.75)
      if (seeded !== pattern) {
        writeSeed(gl, seedTex, pattern)
        gl.activeTexture(gl.TEXTURE0)
        gl.bindTexture(gl.TEXTURE_2D, seedTex)
        paint(gl, loop, seed, pair.write, GRID, GRID)
        pair.swap()
        seeded = pattern
      }
      const rates = patternRates(pattern)
      gl.useProgram(step.program)
      gl.uniform2f(step.loc("uRates"), rates.feed, rates.kill)
      gl.uniform1f(step.loc("uReact"), react)
      const steps = stepsForFrame(tuning.current.speed, frame.dt)
      for (let index = 0; index < steps; index += 1) {
        gl.activeTexture(gl.TEXTURE0)
        gl.bindTexture(gl.TEXTURE_2D, pair.read.texture)
        paint(gl, loop, step, pair.write, GRID, GRID)
        pair.swap()
      }
      const [first, second, third] = paletteOf(host, tuning.current.colors)
      gl.useProgram(display.program)
      uniform3(gl, display.loc("uBg"), backdropOf(host))
      uniform3(gl, display.loc("uA"), first)
      uniform3(gl, display.loc("uB"), second)
      uniform3(gl, display.loc("uC"), third)
      gl.uniform1f(display.loc("uScale"), dyeWeight(1, react))
      gl.activeTexture(gl.TEXTURE0)
      gl.bindTexture(gl.TEXTURE_2D, pair.read.texture)
      paint(gl, loop, display, null, frame.size.width, frame.size.height)
    },
    dispose() {
      drop(pair)
    },
  }
}

function liveCaption(pattern: ReactionPattern): string {
  if (pattern === "print") return "Print growing"
  if (pattern === "coral") return "Coral growing"
  return "Spots growing"
}

function ReactionDiffusionField({
  pattern = "spots",
  speed = 1,
  intensity = 0.75,
  colors,
  className,
}: ReactionDiffusionFieldProps) {
  const reduced = usePrefersReducedMotion()
  const hostRef = useRef<HTMLDivElement>(null)
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const sessionRef = useRef<FieldSession | null>(null)
  const tuningRef = useRef<Tuning>({ pattern, speed, intensity, colors })
  const [blocked, setBlocked] = useState(false)
  const chosen = fieldPattern(pattern)
  const still = reduced || blocked

  useEffect(() => {
    tuningRef.current = { pattern, speed, intensity, colors }
  }, [pattern, speed, intensity, colors])

  useEffect(() => {
    if (reduced) return
    const canvas = canvasRef.current
    const host = hostRef.current
    if (!canvas || !host) return
    let gone = false
    let loop: GlLoopHandle | null = null
    loop = mountGlLoop(canvas, {
      host,
      frame: (frame) => {
        if (gone || !loop) return
        if (!sessionRef.current) {
          const session = startSession(loop, host, tuningRef)
          if (!session) {
            gone = true
            loop.dispose()
            setBlocked(true)
            return
          }
          sessionRef.current = session
        }
        sessionRef.current.draw(frame)
      },
    })
    if (!loop) {
      setBlocked(true)
      return () => {
        gone = true
      }
    }
    return () => {
      gone = true
      sessionRef.current?.dispose()
      sessionRef.current = null
      loop?.dispose()
    }
  }, [reduced])

  return (
    <div
      ref={hostRef}
      data-slot="reaction-diffusion-field"
      data-state={still ? "still" : "live"}
      className={cn("relative h-64 w-full overflow-hidden rounded-xl bg-background text-foreground select-none", className)}
    >
      {still ? (
        <div
          data-fallback="still"
          aria-hidden
          className="absolute inset-0"
          style={{ backgroundColor: "var(--background)", backgroundImage: stillPaint(chosen, colors) }}
        />
      ) : (
        <canvas ref={canvasRef} aria-hidden className="absolute inset-0 h-full w-full" />
      )}
      <p className="pointer-events-none relative z-10 p-4 text-sm">{still ? "Pattern at rest" : liveCaption(chosen)}</p>
    </div>
  )
}

export { ReactionDiffusionField }

"use client"

/** 设备像素比上限 1.5。0 或空值按 1。 */
export function cappedDpr(dpr: number): number {
  return Math.min(dpr || 1, 1.5)
}

/** 离开视口或页面隐藏时，连续帧停住。 */
export function shouldDrawFrame(inView: boolean, pageVisible: boolean): boolean {
  return inView && pageVisible
}

export type GlContext = WebGL2RenderingContext | WebGLRenderingContext

export interface GlSize {
  cssWidth: number
  cssHeight: number
  width: number
  height: number
  dpr: number
}

export interface GlFrame {
  gl: GlContext
  time: number
  dt: number
  size: GlSize
}

/** 浮点颜色附件是否可渲染。half 为真时用半精度。 */
export interface FloatSupport {
  renderable: boolean
  half: boolean
}

export interface GlTarget {
  framebuffer: WebGLFramebuffer
  texture: WebGLTexture
  width: number
  height: number
}

export interface GlPair {
  read: GlTarget
  write: GlTarget
  swap: () => void
  resize: (width: number, height: number) => void
  dispose: () => void
}

export interface GlLoopHandle {
  gl: GlContext
  floatSupport: FloatSupport
  dispose: () => void
  size: () => GlSize
  createPair: (width: number, height: number) => GlPair | null
  /** 全屏三角形。顶点属性 location 0，名字是 a。 */
  draw: () => void
}

interface TexFormat {
  internal: number
  format: number
  type: number
}

function isGlContext(value: unknown): value is GlContext {
  if (typeof value !== "object" || value === null) return false
  const record = value as { createShader?: unknown; drawArrays?: unknown; getExtension?: unknown }
  return (
    typeof record.createShader === "function" &&
    typeof record.drawArrays === "function" &&
    typeof record.getExtension === "function"
  )
}

function isWebGL2(gl: GlContext): gl is WebGL2RenderingContext {
  return typeof (gl as WebGL2RenderingContext).drawBuffers === "function"
}

function obtainGl(canvas: HTMLCanvasElement): GlContext | null {
  const attrs: WebGLContextAttributes = {
    alpha: true,
    antialias: false,
    depth: false,
    stencil: false,
    premultipliedAlpha: false,
  }
  try {
    const gl2 = canvas.getContext("webgl2", attrs)
    if (isGlContext(gl2)) return gl2
    const gl = canvas.getContext("webgl", attrs)
    if (isGlContext(gl)) return gl
    return null
  } catch {
    return null
  }
}

function byteFormat(gl: GlContext): TexFormat {
  return { internal: gl.RGBA, format: gl.RGBA, type: gl.UNSIGNED_BYTE }
}

function floatFormat(gl: GlContext, support: FloatSupport): TexFormat {
  if (!support.renderable) return byteFormat(gl)
  if (isWebGL2(gl)) {
    if (support.half) return { internal: gl.RGBA16F, format: gl.RGBA, type: gl.HALF_FLOAT }
    return { internal: gl.RGBA32F, format: gl.RGBA, type: gl.FLOAT }
  }
  return { internal: gl.RGBA, format: gl.RGBA, type: gl.FLOAT }
}

function fillTexture(gl: GlContext, texture: WebGLTexture, width: number, height: number, format: TexFormat) {
  gl.bindTexture(gl.TEXTURE_2D, texture)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE)
  gl.texImage2D(gl.TEXTURE_2D, 0, format.internal, width, height, 0, format.format, format.type, null)
}

function attach(gl: GlContext, framebuffer: WebGLFramebuffer, texture: WebGLTexture) {
  gl.bindFramebuffer(gl.FRAMEBUFFER, framebuffer)
  gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, texture, 0)
  return gl.checkFramebufferStatus(gl.FRAMEBUFFER) === gl.FRAMEBUFFER_COMPLETE
}

function probeFormat(gl: GlContext, format: TexFormat): boolean {
  const texture = gl.createTexture()
  const framebuffer = gl.createFramebuffer()
  if (!texture || !framebuffer) {
    if (texture) gl.deleteTexture(texture)
    if (framebuffer) gl.deleteFramebuffer(framebuffer)
    return false
  }
  fillTexture(gl, texture, 1, 1, format)
  const ok = attach(gl, framebuffer, texture)
  gl.bindFramebuffer(gl.FRAMEBUFFER, null)
  gl.bindTexture(gl.TEXTURE_2D, null)
  gl.deleteTexture(texture)
  gl.deleteFramebuffer(framebuffer)
  return ok
}

function probeFloat(gl: GlContext): FloatSupport {
  if (!isWebGL2(gl)) {
    const textureFloat = gl.getExtension("OES_texture_float")
    const colorBuffer = gl.getExtension("WEBGL_color_buffer_float")
    if (!textureFloat || !colorBuffer) return { renderable: false, half: false }
    return { renderable: probeFormat(gl, { internal: gl.RGBA, format: gl.RGBA, type: gl.FLOAT }), half: false }
  }
  gl.getExtension("EXT_color_buffer_float")
  if (probeFormat(gl, { internal: gl.RGBA16F, format: gl.RGBA, type: gl.HALF_FLOAT })) {
    return { renderable: true, half: true }
  }
  if (probeFormat(gl, { internal: gl.RGBA32F, format: gl.RGBA, type: gl.FLOAT })) {
    return { renderable: true, half: false }
  }
  return { renderable: false, half: false }
}

function destroyTarget(gl: GlContext, target: GlTarget) {
  gl.deleteFramebuffer(target.framebuffer)
  gl.deleteTexture(target.texture)
}

function createTarget(gl: GlContext, width: number, height: number, support: FloatSupport): GlTarget | null {
  const texture = gl.createTexture()
  const framebuffer = gl.createFramebuffer()
  if (!texture || !framebuffer) {
    if (texture) gl.deleteTexture(texture)
    if (framebuffer) gl.deleteFramebuffer(framebuffer)
    return null
  }
  const w = Math.max(1, Math.floor(width))
  const h = Math.max(1, Math.floor(height))
  const preferred = floatFormat(gl, support)
  fillTexture(gl, texture, w, h, preferred)
  let ok = attach(gl, framebuffer, texture)
  if (!ok && preferred.type !== gl.UNSIGNED_BYTE) {
    fillTexture(gl, texture, w, h, byteFormat(gl))
    ok = attach(gl, framebuffer, texture)
  }
  gl.bindFramebuffer(gl.FRAMEBUFFER, null)
  gl.bindTexture(gl.TEXTURE_2D, null)
  if (!ok) {
    gl.deleteTexture(texture)
    gl.deleteFramebuffer(framebuffer)
    return null
  }
  return { framebuffer, texture, width: w, height: h }
}

function resizeTarget(gl: GlContext, target: GlTarget, width: number, height: number, support: FloatSupport) {
  const w = Math.max(1, Math.floor(width))
  const h = Math.max(1, Math.floor(height))
  if (target.width === w && target.height === h) return
  const preferred = floatFormat(gl, support)
  fillTexture(gl, target.texture, w, h, preferred)
  let ok = attach(gl, target.framebuffer, target.texture)
  if (!ok && preferred.type !== gl.UNSIGNED_BYTE) {
    fillTexture(gl, target.texture, w, h, byteFormat(gl))
    ok = attach(gl, target.framebuffer, target.texture)
  }
  gl.bindFramebuffer(gl.FRAMEBUFFER, null)
  gl.bindTexture(gl.TEXTURE_2D, null)
  if (ok) {
    target.width = w
    target.height = h
  }
}

function createPair(gl: GlContext, width: number, height: number, support: FloatSupport): GlPair | null {
  const first = createTarget(gl, width, height, support)
  const second = createTarget(gl, width, height, support)
  if (!first || !second) {
    if (first) destroyTarget(gl, first)
    if (second) destroyTarget(gl, second)
    return null
  }
  const pair: GlPair = {
    read: first,
    write: second,
    swap() {
      const next = pair.read
      pair.read = pair.write
      pair.write = next
    },
    resize(nextWidth, nextHeight) {
      resizeTarget(gl, pair.read, nextWidth, nextHeight, support)
      resizeTarget(gl, pair.write, nextWidth, nextHeight, support)
    },
    dispose() {
      destroyTarget(gl, pair.read)
      destroyTarget(gl, pair.write)
    },
  }
  return pair
}

function measureOf(host: HTMLElement, canvas: HTMLCanvasElement): GlSize {
  const rect = host.getBoundingClientRect()
  const cssWidth = Math.max(1, rect.width || host.clientWidth || 1)
  const cssHeight = Math.max(1, rect.height || host.clientHeight || 1)
  const raw = typeof window === "undefined" ? 1 : window.devicePixelRatio
  const dpr = cappedDpr(typeof raw === "number" ? raw : 1)
  const width = Math.max(1, Math.round(cssWidth * dpr))
  const height = Math.max(1, Math.round(cssHeight * dpr))
  if (canvas.width !== width) canvas.width = width
  if (canvas.height !== height) canvas.height = height
  return { cssWidth, cssHeight, width, height, dpr }
}

function createTriangle(gl: GlContext): WebGLBuffer | null {
  const buffer = gl.createBuffer()
  if (!buffer) return null
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer)
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW)
  gl.bindBuffer(gl.ARRAY_BUFFER, null)
  return buffer
}

function releaseContext(gl: GlContext) {
  gl.getExtension("WEBGL_lose_context")?.loseContext()
}

/**
 * 多 pass 效果共用的原始 WebGL 循环。只管生命周期：成对 framebuffer、全屏三角形、
 * 浮点纹理探测、像素比上限、尺寸、离屏暂停、卸载时释放 context。
 * getContext 拿不到时返回 null，不抛。
 */
export function mountGlLoop(
  canvas: HTMLCanvasElement,
  options: {
    host: HTMLElement
    frame: (frame: GlFrame) => void
  },
): GlLoopHandle | null {
  const gl = obtainGl(canvas)
  if (!gl) return null
  const triangle = createTriangle(gl)
  if (!triangle) {
    releaseContext(gl)
    return null
  }
  const floatSupport = probeFloat(gl)
  let current = measureOf(options.host, canvas)
  let alive = true
  let raf = 0
  let last = 0
  let inView = true
  let pageVisible = document.visibilityState !== "hidden"
  let observer: IntersectionObserver | null = null
  const context = gl

  function poke() {
    if (!alive || raf !== 0) return
    if (!shouldDrawFrame(inView, pageVisible)) return
    raf = requestAnimationFrame(tick)
  }

  function tick(now: number) {
    raf = 0
    if (!alive || !shouldDrawFrame(inView, pageVisible)) return
    const dt = last === 0 ? 0 : Math.min(0.05, (now - last) / 1000)
    last = now
    current = measureOf(options.host, canvas)
    options.frame({ gl: context, time: now / 1000, dt, size: current })
    if (alive) poke()
  }

  function onVisibility() {
    pageVisible = document.visibilityState !== "hidden"
    poke()
  }

  if (typeof IntersectionObserver === "function") {
    inView = false
    observer = new IntersectionObserver((entries) => {
      const entry = entries[entries.length - 1]
      inView = entry ? entry.isIntersecting : true
      poke()
    })
    observer.observe(options.host)
  }
  document.addEventListener("visibilitychange", onVisibility)
  poke()

  return {
    gl,
    floatSupport,
    size: () => current,
    createPair: (width, height) => (alive ? createPair(gl, width, height, floatSupport) : null),
    draw() {
      if (!alive) return
      gl.bindBuffer(gl.ARRAY_BUFFER, triangle)
      gl.enableVertexAttribArray(0)
      gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0)
      gl.drawArrays(gl.TRIANGLES, 0, 3)
    },
    dispose() {
      if (!alive) return
      alive = false
      if (raf !== 0) cancelAnimationFrame(raf)
      raf = 0
      observer?.disconnect()
      document.removeEventListener("visibilitychange", onVisibility)
      gl.bindBuffer(gl.ARRAY_BUFFER, null)
      gl.deleteBuffer(triangle)
      releaseContext(gl)
    },
  }
}

import type { GlContext } from "./gl/gl-loop"

export interface FieldProgram {
  program: WebGLProgram
  loc: (name: string) => WebGLUniformLocation | null
}

function vert(webgl2: boolean) {
  const head = webgl2 ? "#version 300 es\nin vec2 a;\nout vec2 uv;\n" : "attribute vec2 a;\nvarying vec2 uv;\n"
  return `${head}void main(){uv=a*0.5+0.5;gl_Position=vec4(a,0.0,1.0);}`
}

function frag(webgl2: boolean, body: string) {
  const head = webgl2
    ? "#version 300 es\nprecision highp float;\nin vec2 uv;\nout vec4 frag;\n#define TEX texture\n#define WRITE frag\n"
    : "precision highp float;\nvarying vec2 uv;\n#define TEX texture2D\n#define WRITE gl_FragColor\n"
  return head + body
}

export function fieldVertex(webgl2: boolean) {
  return vert(webgl2)
}

/** 把字节种子写进模拟纹理。 */
export function fieldSeed(webgl2: boolean) {
  return frag(
    webgl2,
    `uniform sampler2D uSeed;
void main() {
  WRITE = TEX(uSeed, uv);
}
`,
  )
}

/** Gray-Scott 一步。五点和拉普拉斯，扩散 0.16 / 0.08，欧拉步长 1，强度只乘反应项。 */
export function fieldStep(webgl2: boolean) {
  return frag(
    webgl2,
    `uniform sampler2D uState;
uniform vec2 uTexel;
uniform vec2 uRates;
uniform float uReact;
void main() {
  vec2 c = TEX(uState, uv).rg;
  vec2 n = TEX(uState, uv + vec2(0.0, uTexel.y)).rg;
  vec2 s = TEX(uState, uv - vec2(0.0, uTexel.y)).rg;
  vec2 e = TEX(uState, uv + vec2(uTexel.x, 0.0)).rg;
  vec2 w = TEX(uState, uv - vec2(uTexel.x, 0.0)).rg;
  vec2 lap = n + s + e + w - 4.0 * c;
  float u = c.r;
  float v = c.g;
  float react = clamp(uReact, 0.0, 1.0);
  float uvv = u * v * v * react;
  float feed = uRates.x;
  float kill = uRates.y;
  float nu = u + (0.16 * lap.r - uvv + feed * react * (1.0 - u));
  float nv = v + (0.08 * lap.g + uvv - (feed + kill) * react * v);
  WRITE = vec4(clamp(nu, 0.0, 1.0), clamp(nv, 0.0, 1.0), 0.0, 1.0);
}
`,
  )
}

/** 催化剂浓度乘上着色比例，混进三色。 */
export function fieldDisplay(webgl2: boolean) {
  return frag(
    webgl2,
    `uniform sampler2D uState;
uniform vec3 uBg;
uniform vec3 uA;
uniform vec3 uB;
uniform vec3 uC;
uniform float uScale;
void main() {
  float chem = clamp(TEX(uState, uv).g, 0.0, 1.0);
  vec3 ink = mix(uA, uB, smoothstep(0.0, 1.0, uv.x));
  ink = mix(ink, uC, smoothstep(0.0, 1.0, uv.y) * 0.65);
  WRITE = vec4(mix(uBg, ink, chem * uScale), 1.0);
}
`,
  )
}

function shaderOf(gl: GlContext, type: number, source: string): WebGLShader | null {
  const item = gl.createShader(type)
  if (!item) return null
  gl.shaderSource(item, source)
  gl.compileShader(item)
  if (!gl.getShaderParameter(item, gl.COMPILE_STATUS)) {
    gl.deleteShader(item)
    return null
  }
  return item
}

function compile(gl: GlContext, vertex: string, fragment: string): FieldProgram | null {
  const program = gl.createProgram()
  if (!program) return null
  const vs = shaderOf(gl, gl.VERTEX_SHADER, vertex)
  const fs = shaderOf(gl, gl.FRAGMENT_SHADER, fragment)
  if (!vs || !fs) {
    if (vs) gl.deleteShader(vs)
    if (fs) gl.deleteShader(fs)
    gl.deleteProgram(program)
    return null
  }
  gl.attachShader(program, vs)
  gl.attachShader(program, fs)
  gl.bindAttribLocation(program, 0, "a")
  gl.linkProgram(program)
  gl.deleteShader(vs)
  gl.deleteShader(fs)
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    gl.deleteProgram(program)
    return null
  }
  return { program, loc: (name) => gl.getUniformLocation(program, name) }
}

export function compileField(gl: GlContext, webgl2: boolean): [FieldProgram, FieldProgram, FieldProgram] | null {
  const vertex = fieldVertex(webgl2)
  const seed = compile(gl, vertex, fieldSeed(webgl2))
  const step = compile(gl, vertex, fieldStep(webgl2))
  const display = compile(gl, vertex, fieldDisplay(webgl2))
  if (!seed || !step || !display) {
    if (seed) gl.deleteProgram(seed.program)
    if (step) gl.deleteProgram(step.program)
    if (display) gl.deleteProgram(display.program)
    return null
  }
  return [seed, step, display]
}
